const message = $json.message ?? $json;
const chat = message.chat ?? {};
const sender = message.from ?? {};
let content = '';
let attachmentName = null;
let preliminaryType = 'unknown';

if (typeof message.text === 'string') {
  content = message.text.trim();
  preliminaryType = content ? 'text' : 'unknown';
} else if (Array.isArray(message.photo) && message.photo.length > 0) {
  preliminaryType = 'image';
  attachmentName = 'Telegram image attachment';
  content = '[Telegram image attachment]';
} else if (message.audio) {
  preliminaryType = 'audio';
  attachmentName = message.audio.file_name ?? 'Telegram audio attachment';
  content = '[Telegram audio attachment]';
} else if (message.video) {
  preliminaryType = 'video';
  attachmentName = message.video.file_name ?? 'Telegram video attachment';
  content = '[Telegram video attachment]';
}

return [{
  json: {
    source: 'telegram',
    chat_id: chat.id != null ? String(chat.id) : null,
    user_id: sender.id != null ? String(sender.id) : null,
    message_id: message.message_id != null ? String(message.message_id) : null,
    timestamp: message.date != null ? new Date(message.date * 1000).toISOString() : null,
    content,
    attachment_name: attachmentName,
    preliminary_type: preliminaryType
  }
}];

const event = $json;
const isHttpUrl = /^https?:\/\/[^\s]+$/i.test(event.content);
const input_type = event.preliminary_type === 'text' && isHttpUrl
  ? 'url'
  : event.preliminary_type;

return [{ json: { ...event, input_type } }];

const event = $json;
const request_id = `mock-request-${event.message_id ?? 'unknown'}`;
const supportedTypes = new Set(['text', 'url', 'image', 'audio', 'video']);

if (!event.chat_id || !supportedTypes.has(event.input_type) || !event.content) {
  return [{
    json: {
      contract_version: '1.0',
      request_id,
      status: 'error',
      error: {
        code: 'validation_error',
        message: 'Please send text, a URL, image, audio, or video to test the bot.',
        retryable: false
      },
      chat_id: event.chat_id
    }
  }];
}

try {
  return [{
    json: {
      contract_version: '1.0',
      request_id,
      status: 'success',
      source: { type: event.input_type, value: event.content },
      scan: {
        scan_id: '00000000-0000-4000-8000-000000000001',
        risk_score: 72,
        severity: 'high',
        threat_type: 'phishing',
        confidence: 0.91,
        signals: [
          { id: 'suspicious_wording', summary: 'Mock suspicious wording signal', source: 'module_3c_mock' },
          { id: 'credential_request', summary: 'Mock credential request signal', source: 'module_3c_mock' }
        ],
        explanation: 'Mock detection response for integration testing. No TruthLensAI backend was called.',
        recommendation: 'Do not provide credentials.'
      },
      threat_intelligence: { available: false, status: 'not_requested', iocs: [], enrichment: [] },
      incident: { incident_id: null, status: null, report_id: null },
      actions: [],
      capabilities: { why_suspicious: true, what_to_do: true, full_report: false, feedback: false },
      chat_id: event.chat_id
    }
  }];
} catch (error) {
  return [{
    json: {
      contract_version: '1.0',
      request_id,
      status: 'error',
      error: { code: 'mock_processing_failed', message: 'The test scan could not be prepared. Please try again.', retryable: true },
      chat_id: event.chat_id
    }
  }];
}

const result = $json;
let text;

if (result.status !== 'success') {
  text = `TruthLensAI Test Scan\n\n${result.error?.message ?? 'The test scan could not be completed.'}`;
} else {
  const scan = result.scan;
  const inputType = result.source.type.charAt(0).toUpperCase() + result.source.type.slice(1);
  const confidence = scan.confidence == null ? 'Not assessed' : `${Math.round(scan.confidence * 100)}%`;
  const riskScore = scan.risk_score == null ? 'Not assessed' : String(scan.risk_score);
  text = [
    'TruthLensAI Test Scan (MOCK)',
    '',
    `Input Type: ${inputType}`,
    `Risk Score: ${riskScore}`,
    `Severity: ${scan.severity.toUpperCase()}`,
    `Threat Type: ${scan.threat_type.toUpperCase()}`,
    `Confidence: ${confidence}`,
    '',
    'Explanation:',
    scan.explanation,
    '',
    'Recommendation:',
    scan.recommendation
  ].join('\n');
}

return [{ json: { chat_id: result.chat_id, text } }];
